#if UNITY_EDITOR
using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Build.Reporting;
namespace IslandSystem {
public static class RelicBuild {
 const string D="Assets/IslandSystem/Relic";
 public static void Prepare(){AssetDatabase.Refresh();var importer=(ModelImporter)AssetImporter.GetAtPath(D+"/RelicCore.fbx");importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.SaveAndReimport();
  var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/RelicCore.fbx"));var root=new GameObject("Ancient Relic Core");model.transform.SetParent(root.transform,false);var colors=new Dictionary<string,Color>{{"Relic_Ivory",new Color(.93f,.87f,.72f)},{"Relic_Gold",new Color(.95f,.68f,.22f)},{"Relic_DeepGold",new Color(.43f,.25f,.07f)},{"Relic_Leather",new Color(.24f,.13f,.065f)},{"Relic_Energy",new Color(.08f,.90f,1)},{"Relic_Crystal",new Color(.025f,.65f,.87f)},{"Relic_FacetLight",new Color(.36f,.95f,1)},{"Relic_FacetBlue",new Color(.025f,.29f,.65f)}};
  foreach(var r in model.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){string n=mats[i].name.Replace(" (Instance)","");string p=D+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,p);}if(colors.ContainsKey(n))m.color=colors[n];m.SetFloat("_Metallic",n.Contains("Gold")?.35f:0);m.SetFloat("_Glossiness",n.Contains("Leather")?.18f:.40f);if(n.Contains("Energy")||n.Contains("Crystal")||n.Contains("Facet")){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",new Color(.015f,.12f,.16f));}if(n.Contains("Ivory")){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",new Color(.10f,.085f,.06f));}mats[i]=m;}r.sharedMaterials=mats;}
  PrefabUtility.SaveAsPrefabAsset(root,D+"/Resources/RelicCore.prefab");var renderers=root.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);Debug.Log("RELIC_BOUNDS "+b.size);UnityEngine.Object.DestroyImmediate(root);var line=AssetDatabase.LoadAssetAtPath<Material>(D+"/Resources/RelicProjectionLine.mat");if(!line){line=new Material(Shader.Find("Sprites/Default"));AssetDatabase.CreateAsset(line,D+"/Resources/RelicProjectionLine.mat");}AssetDatabase.SaveAssets();Debug.Log("RELIC_PREPARED");}
 public static void Build(){var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity"},locationPathName="Builds/IslandRelicTrial/IslandRelicTrial.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});if(result.summary.result!=BuildResult.Succeeded)throw new Exception("Relic build failed");File.WriteAllText("Builds/IslandRelicTrial/试玩.cmd","@echo off\r\nstart \"\" \"%~dp0IslandRelicTrial.exe\" -screen-fullscreen 0 -screen-width 1280 -screen-height 720\r\n",System.Text.Encoding.ASCII);File.WriteAllText("Logs/RelicBuildSuccess.txt",DateTime.UtcNow.ToString("O"));}
}
}
#endif
